-- Mechanical Service foundation. Apply after the existing foundation migrations.
CREATE TABLE `job_cards` (`id` VARCHAR(191) NOT NULL, `branch_id` VARCHAR(191) NOT NULL, `customer_id` VARCHAR(191) NOT NULL, `vehicle_id` VARCHAR(191) NOT NULL, `job_no` VARCHAR(50) NOT NULL, `complaint` VARCHAR(1000) NULL, `odometer` INTEGER NULL, `status` ENUM('OPEN','ESTIMATED','APPROVED','IN_PROGRESS','WAITING_PARTS','QUALITY_CHECK','READY_FOR_INVOICE','INVOICED','CLOSED','CANCELLED') NOT NULL DEFAULT 'OPEN', `opened_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `closed_at` DATETIME(3) NULL, `created_by_id` VARCHAR(191) NULL, PRIMARY KEY (`id`), UNIQUE INDEX `job_cards_branch_id_job_no_key` (`branch_id`,`job_no`), INDEX `job_cards_branch_id_status_opened_at_idx` (`branch_id`,`status`,`opened_at`), CONSTRAINT `job_cards_branch_id_fkey` FOREIGN KEY (`branch_id`) REFERENCES `branches`(`id`), CONSTRAINT `job_cards_customer_id_fkey` FOREIGN KEY (`customer_id`) REFERENCES `customers`(`id`), CONSTRAINT `job_cards_vehicle_id_fkey` FOREIGN KEY (`vehicle_id`) REFERENCES `vehicles`(`id`), CONSTRAINT `job_cards_created_by_id_fkey` FOREIGN KEY (`created_by_id`) REFERENCES `users`(`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `service_estimates` (`id` VARCHAR(191) NOT NULL, `job_card_id` VARCHAR(191) NOT NULL, `estimate_no` VARCHAR(50) NOT NULL, `status` ENUM('DRAFT','PENDING_APPROVAL','APPROVED','REJECTED','EXPIRED') NOT NULL DEFAULT 'DRAFT', `notes` VARCHAR(500) NULL, `approved_at` DATETIME(3) NULL, `approved_by_id` VARCHAR(191) NULL, `created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), PRIMARY KEY (`id`), UNIQUE INDEX `service_estimates_estimate_no_key` (`estimate_no`), INDEX `service_estimates_job_card_id_status_idx` (`job_card_id`,`status`), CONSTRAINT `service_estimates_job_card_id_fkey` FOREIGN KEY (`job_card_id`) REFERENCES `job_cards`(`id`) ON DELETE CASCADE, CONSTRAINT `service_estimates_approved_by_id_fkey` FOREIGN KEY (`approved_by_id`) REFERENCES `users`(`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `service_estimate_lines` (`id` VARCHAR(191) NOT NULL, `estimate_id` VARCHAR(191) NOT NULL, `description` VARCHAR(255) NOT NULL, `quantity` DECIMAL(18,4) NOT NULL, `unit_price` DECIMAL(18,4) NOT NULL, `line_type` VARCHAR(20) NOT NULL, `part_id` VARCHAR(191) NULL, PRIMARY KEY (`id`), CONSTRAINT `service_estimate_lines_estimate_id_fkey` FOREIGN KEY (`estimate_id`) REFERENCES `service_estimates`(`id`) ON DELETE CASCADE, CONSTRAINT `service_estimate_lines_part_id_fkey` FOREIGN KEY (`part_id`) REFERENCES `parts`(`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `technician_assignments` (`id` VARCHAR(191) NOT NULL, `job_card_id` VARCHAR(191) NOT NULL, `technician_id` VARCHAR(191) NOT NULL, `assigned_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `released_at` DATETIME(3) NULL, PRIMARY KEY (`id`), INDEX `technician_assignments_job_card_id_released_at_idx` (`job_card_id`,`released_at`), CONSTRAINT `technician_assignments_job_card_id_fkey` FOREIGN KEY (`job_card_id`) REFERENCES `job_cards`(`id`) ON DELETE CASCADE, CONSTRAINT `technician_assignments_technician_id_fkey` FOREIGN KEY (`technician_id`) REFERENCES `users`(`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `labor_operations` (`id` VARCHAR(191) NOT NULL, `job_card_id` VARCHAR(191) NOT NULL, `technician_id` VARCHAR(191) NULL, `description` VARCHAR(255) NOT NULL, `hours` DECIMAL(10,2) NOT NULL, `rate` DECIMAL(18,4) NOT NULL, `performed_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), PRIMARY KEY (`id`), INDEX `labor_operations_job_card_id_performed_at_idx` (`job_card_id`,`performed_at`), CONSTRAINT `labor_operations_job_card_id_fkey` FOREIGN KEY (`job_card_id`) REFERENCES `job_cards`(`id`) ON DELETE CASCADE, CONSTRAINT `labor_operations_technician_id_fkey` FOREIGN KEY (`technician_id`) REFERENCES `users`(`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `service_inspections` (`id` VARCHAR(191) NOT NULL, `job_card_id` VARCHAR(191) NOT NULL, `inspector_id` VARCHAR(191) NULL, `checklist` JSON NOT NULL, `passed` BOOLEAN NOT NULL, `notes` VARCHAR(1000) NULL, `inspected_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), PRIMARY KEY (`id`), INDEX `service_inspections_job_card_id_inspected_at_idx` (`job_card_id`,`inspected_at`), CONSTRAINT `service_inspections_job_card_id_fkey` FOREIGN KEY (`job_card_id`) REFERENCES `job_cards`(`id`) ON DELETE CASCADE, CONSTRAINT `service_inspections_inspector_id_fkey` FOREIGN KEY (`inspector_id`) REFERENCES `users`(`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `service_invoices` (`id` VARCHAR(191) NOT NULL, `job_card_id` VARCHAR(191) NOT NULL, `invoice_no` VARCHAR(50) NOT NULL, `status` ENUM('DRAFT','READY','POSTED','PAID','VOID') NOT NULL DEFAULT 'DRAFT', `subtotal` DECIMAL(18,4) NOT NULL, `tax` DECIMAL(18,4) NOT NULL DEFAULT 0, `total` DECIMAL(18,4) NOT NULL, `journal_entry_id` VARCHAR(191) NULL, `created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `posted_at` DATETIME(3) NULL, PRIMARY KEY (`id`), UNIQUE INDEX `service_invoices_invoice_no_key` (`invoice_no`), INDEX `service_invoices_job_card_id_status_idx` (`job_card_id`,`status`), CONSTRAINT `service_invoices_job_card_id_fkey` FOREIGN KEY (`job_card_id`) REFERENCES `job_cards`(`id`) ON DELETE CASCADE) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
ALTER TABLE `parts_requests` ADD COLUMN `job_card_id` VARCHAR(191) NULL, ADD INDEX `parts_requests_job_card_id_idx` (`job_card_id`), ADD CONSTRAINT `parts_requests_job_card_id_fkey` FOREIGN KEY (`job_card_id`) REFERENCES `job_cards`(`id`) ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE `parts_issues` ADD COLUMN `job_card_id` VARCHAR(191) NULL, ADD COLUMN `request_id` VARCHAR(191) NULL, ADD INDEX `parts_issues_job_card_id_idx` (`job_card_id`), ADD INDEX `parts_issues_request_id_idx` (`request_id`), ADD CONSTRAINT `parts_issues_job_card_id_fkey` FOREIGN KEY (`job_card_id`) REFERENCES `job_cards`(`id`) ON DELETE SET NULL ON UPDATE CASCADE, ADD CONSTRAINT `parts_issues_request_id_fkey` FOREIGN KEY (`request_id`) REFERENCES `parts_requests`(`id`) ON DELETE SET NULL ON UPDATE CASCADE;
